# Generates test/scipy/test_stats_final_discrete.py with scipy 1.18.1.
import numpy as np
import scipy.stats as st

def fl(v):
    v = float(v)
    return repr(v) if np.isfinite(v) else ('nan' if v != v else ('inf' if v > 0 else '-inf'))
def lst(a):
    return "[" + ", ".join(fl(v) for v in np.ravel(a)) + "]"

out = ["# Copyright (C) 2026 the Typhon authors",
       "# Expected values generated by test/scipy/gen_stats_final_discrete.py (scipy 1.18.1).",
       "import numpy as np", "import scipy.stats as st", "nan = float('nan')", "inf = float('inf')", "",
       "def close(x, ref, rtol: float = 1e-8, atol: float = 1e-12) -> bool:",
       "    a = np.asarray(x).astype(float).ravel()",
       "    r = np.asarray(ref).astype(float).ravel()",
       "    if a.shape != r.shape:",
       "        print('shape', a.shape, r.shape)",
       "        return False",
       "    ok = True",
       "    for i in range(a.shape[0]):",
       "        u = float(a[i])",
       "        v = float(r[i])",
       "        if not (abs(u - v) <= atol + rtol * abs(v) or (u != u and v != v) or u == v):",
       "            print('mismatch', i, u, v)",
       "            ok = False",
       "    return ok", ""]
cases = [('fisher', 'nchypergeom_fisher', (140, 80, 60, 0.5)), ('fisher2', 'nchypergeom_fisher', (25, 10, 12, 3.0)),
         ('wall', 'nchypergeom_wallenius', (140, 80, 60, 0.5)), ('wall2', 'nchypergeom_wallenius', (25, 10, 12, 3.0))]
for tag, name, a in cases:
    d = getattr(st, name)
    ks = np.arange(int(d.support(*a)[0]), int(d.support(*a)[1]) + 1)
    ks = ks[::max(1, len(ks) // 8)]
    qs = [0.05, 0.3, 0.5, 0.7, 0.95]
    out.append(f"@test\ndef test_{tag}():")
    out.append(f"    d = st.{name}")
    out.append(f"    a = {a!r}")
    out.append(f"    ks = {lst(ks)}")
    out.append(f"    assert close(d.pmf(ks, *a), {lst(d.pmf(ks, *a))}, 1e-7)")
    out.append(f"    assert close(d.cdf(ks, *a), {lst(d.cdf(ks, *a))}, 1e-7)")
    out.append(f"    assert close(d.sf(ks, *a), {lst(d.sf(ks, *a))}, 1e-7)")
    out.append(f"    assert close(d.ppf({qs!r}, *a), {lst(d.ppf(qs, *a))})")
    m, v = d.stats(*a, moments='mv')
    out.append(f"    assert close([d.mean(*a), d.var(*a)], {lst([m, v])}, 1e-7)")
    out.append(f"    assert close(d.rvs(*a, size=6, random_state=np.random.RandomState(1234)), {lst(d.rvs(*a, size=6, random_state=np.random.RandomState(1234)))})")
    out.append(f"    assert close(d.rvs(*a, size=6, random_state=np.random.default_rng(42)), {lst(d.rvs(*a, size=6, random_state=np.random.default_rng(42)))})")
    out.append("")
p = [0.1, 0.35, 0.6, 0.8, 0.25, 0.9]
d = st.poisson_binom
ks = [-1, 0, 1, 2, 3, 4, 5, 6, 7]
out.append("@test\ndef test_poisson_binom():")
out.append(f"    p = {p!r}")
out.append(f"    ks = {ks!r}")
out.append(f"    assert close(st.poisson_binom.pmf(ks, p), {lst(d.pmf(ks, p))})")
out.append(f"    assert close(st.poisson_binom.cdf(ks, p), {lst(d.cdf(ks, p))})")
out.append(f"    assert close(st.poisson_binom.sf(ks, p), {lst(d.sf(ks, p))})")
out.append(f"    assert close(st.poisson_binom.ppf([0.05, 0.5, 0.95], p), {lst(d.ppf([0.05, 0.5, 0.95], p))})")
out.append(f"    assert close(st.poisson_binom.stats(p, moments='mv'), {lst(d.stats(p, moments='mv'))})")
out.append(f"    assert close(st.poisson_binom(p, loc=2).pmf([2, 3, 4]), {lst(d(p, loc=2).pmf([2, 3, 4]))})")
out.append(f"    assert close(st.poisson_binom.rvs(p, size=5, random_state=np.random.RandomState(7)), {lst(d.rvs(p, size=5, random_state=np.random.RandomState(7)))})")
print("\n".join(out))
